#!/usr/bin/env node
/**
 * THE ONE FUNCTIONALITY REGISTRY — summary tables (owner order 2026-10-21).
 *
 * docs/master/LABOURMARKET-FUNCTIONAL-AUDIT.md §2 is the registry: one row per
 * process, with its status, evidence, dependency, owner area (1–18) and role.
 * This script derives the §1 summary tables from those rows, so the counts can
 * never drift from the rows they count.
 *
 *   node .github/scripts/registry-summary.mjs           # rewrite §1 in place
 *   node .github/scripts/registry-summary.mjs --check   # exit 1 when §1 is stale
 *
 * No network, no database. Guarded by lib/guards/functional-registry-summary.test.ts.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const DOC = join(ROOT, "docs", "master", "LABOURMARKET-FUNCTIONAL-AUDIT.md");

/** The owner's six statuses (2026-10-21), in report order. */
export const STATUSES = [
  "LIVE_PROVEN",
  "IMPLEMENTED_UNVERIFIED",
  "PARTIAL",
  "BROKEN",
  "NOT_BUILT",
  "BLOCKED",
];
/** Rows kept for traceability that are not processes of their own. */
export const NOT_COUNTED = ["DUPLICATE", "RETIRED"];

/** The owner's 18 areas (2026-10-21). */
export const OWNER_AREAS = {
  1: "Registration, sign-in, profiles",
  2: "Work Journal",
  3: "Living CV, skills, confirmations, recognition",
  4: "Companies and organizations",
  5: "Projects, objects, tasks",
  6: "Brigades and B2B",
  7: "Calendar, planning, hours",
  8: "Job offers, needs, applications",
  9: "Worker search, matching, recommendations",
  10: "Conversations, invitations, notifications; chat, AI and MCP doors",
  11: "Universal marketplace",
  12: "Orders, bookings, execution",
  13: "Payments: Stripe, LMC, subscriptions, invoices",
  14: "Documents, contracts, approvals",
  15: "History, data value, reports",
  16: "Privacy, GDPR, security",
  17: "International, languages, devices",
  18: "Admin, marketing, analytics, operations",
};

const START = "<!-- registry-summary:start (generated by .github/scripts/registry-summary.mjs — do not edit by hand) -->";
const END = "<!-- registry-summary:end -->";

export function parseRows(text) {
  const body = text.split("## 2. Per-area status")[1]?.split("\n## 3.")[0];
  if (!body) throw new Error("§2 Per-area status not found");
  const rows = [];
  let area = 0;
  let areaTitle = "";
  for (const line of body.split("\n")) {
    const h = line.match(/^### Area (\d+) — (.*)$/);
    if (h) {
      area = Number(h[1]);
      areaTitle = h[2].trim();
      continue;
    }
    const m = line.match(/^\|\s*(\d+\.\d+)\s*\|(.*)\|\s*$/);
    if (!m) continue;
    const cells = m[2].split("|").map((c) => c.trim());
    if (cells.length !== 6) throw new Error(`row ${m[1]}: expected 6 cells after the ID, found ${cells.length}`);
    const status = (cells[1].match(/^[A-Z_]+/) ?? [""])[0];
    if (!STATUSES.includes(status) && !NOT_COUNTED.includes(status)) {
      throw new Error(`row ${m[1]}: unknown status "${cells[1].slice(0, 40)}"`);
    }
    const ownerArea = Number(cells[4]);
    if (!OWNER_AREAS[ownerArea]) throw new Error(`row ${m[1]}: owner area "${cells[4]}" is not 1–18`);
    if (!cells[5]) throw new Error(`row ${m[1]}: role is empty`);
    rows.push({ id: m[1], area, areaTitle, feature: cells[0], status, ownerArea, role: cells[5] });
  }
  const ids = new Set();
  for (const r of rows) {
    if (ids.has(r.id)) throw new Error(`duplicate row id ${r.id}`);
    ids.add(r.id);
  }
  return rows;
}

function table(groups, label) {
  const head = `| ${label} | ${STATUSES.join(" | ")} | Processes | LIVE_PROVEN share | Not counted |`;
  const sep = `|${"---|".repeat(STATUSES.length + 4)}`;
  const lines = [head, sep];
  const total = Object.fromEntries([...STATUSES, ...NOT_COUNTED].map((s) => [s, 0]));
  for (const [name, rs] of groups) {
    const c = Object.fromEntries([...STATUSES, ...NOT_COUNTED].map((s) => [s, 0]));
    for (const r of rs) {
      c[r.status] += 1;
      total[r.status] += 1;
    }
    const n = STATUSES.reduce((a, s) => a + c[s], 0);
    const nc = NOT_COUNTED.reduce((a, s) => a + c[s], 0);
    lines.push(`| ${name} | ${STATUSES.map((s) => c[s]).join(" | ")} | ${n} | ${c.LIVE_PROVEN}/${n} | ${nc} |`);
  }
  const n = STATUSES.reduce((a, s) => a + total[s], 0);
  const nc = NOT_COUNTED.reduce((a, s) => a + total[s], 0);
  lines.push(
    `| **Total** | ${STATUSES.map((s) => `**${total[s]}**`).join(" | ")} | **${n}** | **${total.LIVE_PROVEN}/${n}** | ${nc} |`,
  );
  return { lines, total, n, nc };
}

export function renderSummary(rows) {
  const byOwner = Object.keys(OWNER_AREAS).map((k) => [
    `${k} ${OWNER_AREAS[k]}`,
    rows.filter((r) => r.ownerArea === Number(k)),
  ]);
  const owner = table(byOwner, "Owner area");
  const areas = [...new Set(rows.map((r) => r.area))].sort((a, b) => a - b);
  const byAudit = areas.map((a) => {
    const rs = rows.filter((r) => r.area === a);
    return [`${a} ${rs[0].areaTitle}`, rs];
  });
  const audit = table(byAudit, "Audit section (§2)");
  return [
    START,
    "",
    `**${owner.total.LIVE_PROVEN} of ${owner.n} processes are LIVE_PROVEN.** ` +
      `${owner.n} processes are counted. ${owner.nc} more rows are kept for traceability but not counted: ` +
      `duplicates of another row, or retired code.`,
    "",
    "### 1a. By the owner's 18 areas",
    "",
    ...owner.lines,
    "",
    "### 1b. By audit section (where each row lives in §2)",
    "",
    ...audit.lines,
    "",
    END,
  ].join("\n");
}

function main() {
  const text = readFileSync(DOC, "utf8");
  const rows = parseRows(text);
  const summary = renderSummary(rows);
  const a = text.indexOf(START);
  const b = text.indexOf(END);
  if (a < 0 || b < 0) throw new Error("summary markers not found in §1");
  const next = text.slice(0, a) + summary + text.slice(b + END.length);
  if (process.argv.includes("--check")) {
    if (next !== text) {
      console.error("registry summary is stale: run node .github/scripts/registry-summary.mjs");
      process.exit(1);
    }
    console.log(`registry summary current: ${rows.length} rows`);
    return;
  }
  writeFileSync(DOC, next);
  console.log(`registry summary written: ${rows.length} rows`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) main();
